impl UnifiedScanArgs {
    pub fn has_row_index_or_slice(&self) -> bool {
        self.row_index.is_some() || self.pre_slice.is_some()
    }

    pub(crate) fn has_per_scan_state(&self) -> bool {
        self.row_index.is_some()
            || self.pre_slice.is_some()
            || self.deletion_files.is_some()
            || self.table_statistics.is_some()
            || self.default_values.is_some()
    }


    pub(crate) fn can_concat_sources(&self, other: &Self) -> bool {
        !self.has_per_scan_state()
            && !other.has_per_scan_state()
            && self.concat_key() == other.concat_key()
    }


    fn concat_key(&self) -> impl PartialEq + '_ {
        let Self {
            schema,
            cloud_options,
            hive_options,
            rechunk: _,
            cache,
            glob,
            expand_paths,
            hidden_file_prefix,
            projection,
            column_mapping,
            default_values: _,
            row_index: _,
            pre_slice: _,
            cast_columns_policy,
            missing_columns_policy,
            extra_columns_policy,
            include_file_paths,
            deletion_files: _,
            table_statistics: _,
            row_count: _,
            source_sizes: _,
            resolve_heavy_sources,
        } = self;
        (
            (
                schema,
                cloud_options,
                hive_options,
                cache,
                glob,
                expand_paths,
            ),
            (
                hidden_file_prefix,
                projection,
                column_mapping,
                cast_columns_policy,
            ),
            (
                missing_columns_policy,
                extra_columns_policy,
                include_file_paths,
                resolve_heavy_sources,
            ),
        )
    }

    pub(crate) fn concat_sources(parts: &[&Self]) -> Self {
        let mut out = parts[0].clone();
        out.row_count = parts
            .iter()
            .map(|args| args.row_count)
            .try_fold((0, 0), |(physical, deleted), count| {
                count.map(|(p, d)| (physical + p, deleted + d))
            });
        out.source_sizes = parts
            .iter()
            .all(|args| args.source_sizes.is_some())
            .then(|| {
                parts
                    .iter()
                    .flat_map(|args| args.source_sizes.as_deref().unwrap().iter().copied())
                    .collect()
            });
        out
    }
}


impl Default for UnifiedScanArgs {
    fn default() -> Self {
        Self {
            schema: None,
            cloud_options: None,
            hive_options: HiveOptions::new_enabled(),
            rechunk: false,
            cache: false,
            glob: true,
            expand_paths: true,
            hidden_file_prefix: None,
            projection: None,
            column_mapping: None,
            default_values: None,
            row_index: None,
            pre_slice: None,
            cast_columns_policy: CastColumnsPolicy::default(),
            missing_columns_policy: MissingColumnsPolicy::default(),
            extra_columns_policy: ExtraColumnsPolicy::default(),
            include_file_paths: None,
            deletion_files: None,
            table_statistics: None,
            row_count: None,
            source_sizes: None,
            resolve_heavy_sources: None,
        }
    }
}

